431  find_armor_header(const char *buf, size_t len, size_t *hdrlen)
   432  {
   433      int st = -1;
   434
   435      for (unsigned i = 0; i < len - 10; i++) {
   436          if ((buf[i] == CH_DASH) && !strncmp(&buf[i + 1], ST_DASHES, 4)) {
   437              st = i;
   438              break;
   439          }
   440      }
   441
   442      if (st < 0) {
   443          return NULL;
   444      }
   445
   446      for (unsigned i = st + 5; i <= len - 5; i++) {
   447          if ((buf[i] == CH_DASH) && !strncmp(&buf[i + 1], ST_DASHES, 4)) {
   448              *hdrlen = i + 5 - st;
   449              return &buf[st];
   450          }
   451      }
   452
   453      return NULL;
   454  }
